// Normaliza payload do Maestr.ia
const body = $input.item.json.body || $input.item.json;
const creds = $('Credenciais e Config').first().json;

return [{ json: {
  clickup_api_key:      creds.clickup_api_key,
  supabase_url:         creds.supabase_url,
  supabase_service_key: creds.supabase_service_key,
  clickup_task_id:      body.clickup_task_id,
  task_id:              body.task_id,
  comment_id:           body.comment_id,
  author_name:          body.author_name || 'Maestr.ia',
  content:              body.content || ''
}}];

// Normaliza webhook do ClickUp
// O ClickUp envia: { event: 'taskCommentPosted', task_id, comment: { id, text_content, user: { username, email } } }
const body = $input.item.json.body || $input.item.json;
const creds = $('Credenciais e Config').first().json;

const event = body.event || '';
if (event !== 'taskCommentPosted') {
  return [{ json: { skip: true, reason: 'not a comment event: ' + event } }];
}

const clickupTaskId = body.task_id || null;
const comment = body.comment || {};
const commentId = String(comment.id || '');
const content = comment.text_content || comment.comment_text || '';
const user = comment.user || {};
const authorName = user.username || user.email || 'ClickUp User';
const authorEmail = user.email || null;

if (!clickupTaskId || !commentId || !content) {
  return [{ json: { skip: true, reason: 'missing required fields' } }];
}

return [{ json: {
  clickup_api_key:      creds.clickup_api_key,
  supabase_url:         creds.supabase_url,
  supabase_service_key: creds.supabase_service_key,
  clickup_task_id:      clickupTaskId,
  clickup_comment_id:   commentId,
  author_name:          authorName,
  author_email:         authorEmail,
  content
}}];

const tasks = $input.item.json;
const prev = $('Normalizar - ClickUp').first().json;

const task = Array.isArray(tasks) ? tasks[0] : null;
if (!task?.id) {
  return [{ json: { skip: true, reason: 'task not found for clickup_task_id: ' + prev.clickup_task_id } }];
}

return [{ json: {
  ...prev,
  task_id:         task.id,
  organization_id: task.organization_id
}}];

const prev = $('Normalizar - ClickUp').first().json;
console.log('[skip] ' + (prev.reason || 'unknown'));
return [{ json: { skipped: true } }];
